import React, { useState, useEffect } from 'react';
import { createUser } from '../services/api';
import { getFranchises } from '../services/api'; // Import API function to get franchises
import UserManagement from './UserManagement'; // Assuming the path is correct

const CreateUserSuperAdmin = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user', // Default value
    franchiseId: '',
  });

  const [franchises, setFranchises] = useState([]); // State to store the franchises
  const [isSuperAdminExists, setIsSuperAdminExists] = useState(false); // State to check if super admin exists

  // Fetch the list of franchises when the component mounts
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data); // Store the franchise data
      } catch (error) {
        alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
      }
    };
    fetchFranchises();
  }, []); // Empty dependency array to run only once when the component mounts

  // Check if a super admin already exists
  useEffect(() => {
    const checkSuperAdminExistence = async () => {
      try {
        const response = await getFranchises(); // Assuming it returns franchises with an admin field
        const superAdminExists = response.data.some(franchise => franchise.admin && franchise.admin.role === 'superadmin');
        setIsSuperAdminExists(superAdminExists);
      } catch (error) {
        alert('Error checking super admin existence: ' + (error.response?.data?.message || error.message));
      }
    };
    checkSuperAdminExistence();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // If the role is superadmin and one already exists, show error alert
    if (formData.role === 'superadmin' && isSuperAdminExists) {
      alert('Only one superadmin can be created for all franchises.');
      return;
    }

    try {
      await createUser(formData); // Use the utility function to create user
      alert('User created successfully!');
      window.location.reload(); // Reload page to reflect changes
    } catch (error) {
      alert('Error creating user: ' + (error.response?.data?.message || error.message));
    }
  };

  return (
    <div>
      <h1>Create Super Admin</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="username">Username:</label>
          <input
            id="username"
            name="username"
            placeholder="Username"
            value={formData.username}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="password">Password:</label>
          <input
            id="password"
            name="password"
            type="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="role">Role:</label>
          <select
            id="role"
            name="role"
            value={formData.role}
            onChange={handleChange}
            disabled={isSuperAdminExists} // Disable role selection if superadmin already exists
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
            <option value="superadmin" disabled={isSuperAdminExists}>Super Admin</option>
          </select>
        </div>
        <div>
          <label htmlFor="franchiseId">Franchise:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={formData.franchiseId}
            onChange={handleChange}
            required
          >
            <option value="">Select a Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name} - {franchise.location}
              </option>
            ))}
          </select>
        </div>
        <button type="submit">Create User</button>
      </form>
      <UserManagement />
    </div>
  );
};

export default CreateUserSuperAdmin;
